import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第六十二卦 小过 雷山小过 震上艮下","description":"周易 - 第六十二卦 小过 雷山小过 震上艮下","frontmatter":{"title":"第六十二卦 小过 雷山小过 震上艮下","description":"周易 - 第六十二卦 小过 雷山小过 震上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/063.md","filePath":"zh/classics/zhouyi/063.md"}'),l={name:"zh/classics/zhouyi/063.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="小过" tabindex="-1">小过 <a class="header-anchor" href="#小过" aria-label="Permalink to “小过”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉，有飞鸟遗之音，不宜上宜下，大吉；上逆而下顺 也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>飞鸟以凶。象 曰：飞鸟以凶，不可如何也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>过其祖，遇其妣；不及其君，遇其臣；无咎。象曰：不及其君，臣不可过也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>弗过防之，从或戕之，凶。象曰：从或戕之，凶如何也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>无咎，弗过遇之。往厉必戒，勿用永贞。象曰：弗过遇之，位不当也。往厉必戒，终不可长也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>密云不雨，自我西郊，公弋取彼在穴。象曰：密云不雨，已上也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>弗遇过之，飞鸟离之，凶，是谓灾眚。象曰：弗遇过之，已亢也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
